#!/usr/bin/env python3
from PIL import Image
import sys
import numpy as np

def analyze_image(file_path):
    print(f"Analyzing {file_path}...")
    img = Image.open(file_path)
    width, height = img.size
    print(f"Image dimensions: {width} x {height}")

    # Convert to numpy array for easier analysis
    img_array = np.array(img)
    print(f"Image array shape: {img_array.shape}")

    # Check for unusual pixels
    unique_pixels = set()
    for y in range(height):
        for x in range(width):
            pixel = tuple(img_array[y, x])
            unique_pixels.add(pixel)

    print(f"Number of unique pixel values: {len(unique_pixels)}")
    print("Unique pixel values:")
    for pixel in sorted(unique_pixels):
        print(f"  {pixel}")

    # Look for patterns in first few rows
    print("\nSampling first few pixels of each row:")
    for y in range(min(10, height)):
        row_sample = img_array[y, :min(20, width)]
        print(f"Row {y}: {row_sample}")

    # Analyze the image for binary pattern
    print("\nChecking for binary pattern in rows...")
    binary_rows = []
    for y in range(height):
        binary_row = ""
        for x in range(width):
            pixel = tuple(img_array[y, x])
            if pixel == (0, 0, 0):  # Black pixel
                binary_row += "0"
            else:  # Non-black pixel (could be white or other color)
                binary_row += "1"

        # Only print non-empty rows (having both 0s and 1s)
        if "0" in binary_row and "1" in binary_row:
            print(f"Row {y}: {binary_row[:20]}... (length: {len(binary_row)})")
            binary_rows.append(binary_row)

    # Try to decode binary rows to ASCII
    print("\nAttempting to decode binary rows to ASCII:")
    for idx, binary in enumerate(binary_rows):
        if len(binary) >= 8:
            # Group the binary into 8-bit chunks
            ascii_text = ""
            for i in range(0, len(binary), 8):
                if i + 8 <= len(binary):
                    byte = binary[i:i+8]
                    try:
                        ascii_text += chr(int(byte, 2))
                    except:
